            pair.setSecond(100L);
            dodgyWAL.archive(pair);
        } catch (Throwable ioe) {
        }
        while (true) {
            try {
                // one more abort needs to be called
                verify(services, atLeast(2)).abort(anyString(), any());
                break;
            } catch (WantedButNotInvoked t) {
                Threads.sleep(1);
            }
